CREATE TABLE telegram_destinations(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES owners(id),bot_id INTEGER NOT NULL,chat_id INTEGER NOT NULL,topic_id INTEGER NOT NULL DEFAULT 0,conversation_id TEXT NOT NULL REFERENCES conversations(id),private INTEGER NOT NULL,UNIQUE(owner_id,bot_id,chat_id,topic_id),UNIQUE(conversation_id));
CREATE TABLE telegram_events(owner_id TEXT NOT NULL REFERENCES owners(id),bot_id INTEGER NOT NULL,update_id INTEGER NOT NULL,payload TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','done','failed','rejected')),attempts INTEGER NOT NULL DEFAULT 0,available_at REAL NOT NULL,received_at REAL NOT NULL,error TEXT,PRIMARY KEY(owner_id,bot_id,update_id));
CREATE TABLE telegram_messages(owner_id TEXT NOT NULL REFERENCES owners(id),bot_id INTEGER NOT NULL,chat_id INTEGER NOT NULL,message_id INTEGER NOT NULL,conversation_id TEXT NOT NULL REFERENCES conversations(id),canonical_id TEXT REFERENCES messages(id) ON DELETE SET NULL,job_id TEXT REFERENCES jobs(id),action_id TEXT REFERENCES actions(id),revision INTEGER NOT NULL DEFAULT 1,edited_at REAL NOT NULL,body TEXT NOT NULL,PRIMARY KEY(owner_id,bot_id,chat_id,message_id));
CREATE TABLE telegram_revisions(owner_id TEXT NOT NULL,bot_id INTEGER NOT NULL,chat_id INTEGER NOT NULL,message_id INTEGER NOT NULL,revision INTEGER NOT NULL,body TEXT NOT NULL,recorded_at REAL NOT NULL,PRIMARY KEY(owner_id,bot_id,chat_id,message_id,revision));
CREATE TABLE telegram_albums(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,bot_id INTEGER NOT NULL,chat_id INTEGER NOT NULL,group_id TEXT NOT NULL,conversation_id TEXT NOT NULL REFERENCES conversations(id),first_at REAL NOT NULL,last_at REAL NOT NULL,status TEXT NOT NULL DEFAULT 'pending',job_id TEXT REFERENCES jobs(id));
CREATE TABLE telegram_album_items(album_id TEXT NOT NULL REFERENCES telegram_albums(id),message_id INTEGER NOT NULL,update_id INTEGER NOT NULL,body TEXT NOT NULL,PRIMARY KEY(album_id,message_id));
CREATE TABLE telegram_callbacks(token TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES owners(id),conversation_id TEXT NOT NULL REFERENCES conversations(id),action_id TEXT NOT NULL REFERENCES actions(id),operation TEXT NOT NULL,body TEXT NOT NULL,expires_at REAL NOT NULL,status TEXT NOT NULL DEFAULT 'pending',result TEXT);
CREATE TABLE telegram_polls(poll_id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,bot_id INTEGER NOT NULL,chat_id INTEGER NOT NULL,message_id INTEGER NOT NULL,conversation_id TEXT NOT NULL REFERENCES conversations(id),body TEXT NOT NULL);
CREATE TABLE telegram_previews(job_id TEXT PRIMARY KEY REFERENCES jobs(id),generation INTEGER NOT NULL,draft_id INTEGER NOT NULL,chat_id INTEGER NOT NULL,topic_id INTEGER NOT NULL DEFAULT 0);
CREATE TABLE resource_scopes(kind TEXT NOT NULL,resource_id TEXT NOT NULL,conversation_id TEXT NOT NULL REFERENCES conversations(id),PRIMARY KEY(kind,resource_id));
CREATE TABLE telegram_file_cache(bot_id INTEGER NOT NULL,artifact_id TEXT NOT NULL REFERENCES artifacts(id),operation TEXT NOT NULL,file_id TEXT NOT NULL,PRIMARY KEY(bot_id,artifact_id,operation));
CREATE INDEX telegram_events_ready ON telegram_events(owner_id,bot_id,status,available_at);
CREATE INDEX resource_scopes_conversation ON resource_scopes(conversation_id,kind);
